// [MEDIUM_PRIORITY] UX_POLISH: Empty state handled
// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.voice.proactiveimport java.time.DayOfWeekimport java.time.LocalTime/** * NOUS — Proactive Intelligence data model (§11 Proactive Intelligence). * * Represents the situations in which NOUS speaks first — without being * prompted by a wake word. This is what makes NOUS feel like a *companion* * rather than a *command-response tool*. * * ## Trigger types (§11 When NOUS Speaks First) * * | Type                | Example                                                 | Priority | * |---------------------|---------------------------------------------------------|----------| * | MORNING_BRIEFING    | "Good morning, sir. It's 7 AM. Shall I brief you?"      | 5        | * | CALENDAR_REMINDER   | "Your meeting with Dr. Smith starts in 15 minutes."     | 8        | * | BATTERY_LOW         | "Battery is at 5%. Shall I enable power saving mode?"   | 9        | * | WEATHER_ALERT       | "It's going to rain in 30 minutes."                     | 6        | * | MISSED_CALLS        | "Your mother called twice. Shall I call her back?"      | 7        | * | HEALTH_REMINDER     | "You've been sitting for 2 hours. Want me to stretch?"  | 4        | * | SECURITY_ALERT      | "An unknown device connected to your Wi-Fi."            | 9        | * | ROUTINE             | "It's 10 PM. Shall I dim the lights and set your alarm?"| 5        | * | HABIT_SUGGESTION    | "I noticed you usually open camera at 8 AM. Shall I?"   | 6        | * * ## Priority semantics * *  - 1–3  → low (CALM emotion, never interrupts) *  - 4–7  → normal (NEUTRAL emotion, can speak during normal hours) *  - 8–10 → high (URGENT emotion, can interrupt silent hours + proactive barge-in) * * The [ProactiveEngine.shouldSpeak] method uses priority to decide whether * a trigger fires during silent hours (10 PM–7 AM) per §25 Q5. * * ## Habit suggestions * * HABIT_SUGGESTION is a special case — it's generated by [HabitTracker] * (v2 fix #7) from observed user patterns in the Memory Module, not from * a fixed rule. See [HabitTracker] for details. * * @see <a href="docs/strategy/module-5-strategy-v2.md">§11 Proactive Intelligence, §25 Q5 silent hours</a> *//** * One proactive trigger — a situation in which NOUS might speak first. * * @param type         the kind of trigger (drives message template + priority). * @param message      the text NOUS will speak if [ProactiveEngine.shouldSpeak] passes. * @param priority     1–10 (higher = more important; 8+ interrupts silent hours). * @param timestampMs  when the trigger was created (for dedup + ordering). * @param metadata     optional structured data (e.g. caller name for MISSED_CALLS). */data class ProactiveTrigger(    val type: TriggerType,    val message: String,    val priority: Int,    val timestampMs: Long = System.currentTimeMillis(),    val metadata: Map<String, String> = emptyMap(),) {    init {        require(priority in 1..10) { "priority must be 1..10, got $priority" }        require(message.isNotBlank()) { "message must not be blank" }    }    /** True if this trigger is urgent enough to interrupt silent hours. */    val interruptsSilentHours: Boolean get() = priority >= SilentHours.SILENT_HOURS_INTERRUPT_THRESHOLD    /** True if this trigger is urgent enough to proactive-barge-in (per §13). */    val allowsProactiveBargeIn: Boolean get() = priority >= SilentHours.PROACTIVE_BARGE_IN_THRESHOLD}// ──────────────────────────────────────────────────────────────────────────/** Types of proactive triggers (§11 + HabitTracker from §20). */enum class TriggerType {    /** Morning briefing at user's usual wake time. */    MORNING_BRIEFING,    /** Calendar event starting soon. */    CALENDAR_REMINDER,    /** Battery critically low. */    BATTERY_LOW,    /** Weather change (rain, storm, etc.). */    WEATHER_ALERT,    /** Missed calls from same caller. */    MISSED_CALLS,    /** Health reminder (sedentary, hydration, etc.). */    HEALTH_REMINDER,    /** Security event (unknown device, suspicious login). */    SECURITY_ALERT,    /** Routine action at habitual time (lights off at 10 PM). */    ROUTINE,    /** Habit-based suggestion from [HabitTracker] (v2 fix #7). */    HABIT_SUGGESTION,}// ──────────────────────────────────────────────────────────────────────────/** * Silent-hours policy (§25 Q5). * * NOUS doesn't speak proactively during silent hours (default 10 PM–7 AM) * unless the trigger priority is ≥ [SILENT_HOURS_INTERRUPT_THRESHOLD] (8). * * User can customize the silent-hours window in Settings → Privacy → Voice. * * ## Testability * * Pure data class + `contains(time)` method — fully testable without * Android dependencies. Tests construct any time-of-day and verify whether * it falls in silent hours. */data class SilentHours(    val start: LocalTime = DEFAULT_START,    val end: LocalTime = DEFAULT_END,    val enabledDays: Set<DayOfWeek> = DayOfWeek.entries.toSet(),) {    init {        require(start != end) { "start and end must differ" }        require(enabledDays.isNotEmpty()) { "enabledDays must not be empty" }    }    /**     * True if [time] falls within these silent hours on [day].     *     * Handles wrap-around midnight: if start > end (e.g. 22:00 → 07:00),     * the silent period spans midnight.     */    fun contains(time: LocalTime, day: DayOfWeek): Boolean {        if (day !in enabledDays) return false        return if (start <= end) {            // Same-day window (e.g. 13:00 → 14:00 for afternoon quiet).            time in start..end        } else {            // Wrap-around window (e.g. 22:00 → 07:00 — spans midnight).            time >= start || time <= end        }    }    /** True if silent hours are currently in effect (uses system clock). */    fun isActiveNow(): Boolean {        val now = LocalTime.now()        val today = java.time.LocalDate.now().dayOfWeek        return contains(now, today)    }    companion object {        /** Default silent hours: 10 PM – 7 AM (per §25 Q5). */        val DEFAULT_START: LocalTime = LocalTime.of(22, 0)        val DEFAULT_END: LocalTime = LocalTime.of(7, 0)        /** Priority required to interrupt silent hours. */        const val SILENT_HOURS_INTERRUPT_THRESHOLD = 8        /** Priority required for proactive barge-in (per §13). */        const val PROACTIVE_BARGE_IN_THRESHOLD = 8    }}